<script setup>
import { computed, onBeforeUnmount, ref } from "vue"
import { useRouter } from "vue-router"
defineProps({compact:{type:Boolean,default:false}})
const router=useRouter(),state=ref("紧绷"),minutes=ref(3),remaining=ref(0),message=ref("")
let timer,deadline=0
const step=ref(0)
const steps={
 '紧绷':['把注意力带到肩膀。轻轻松开，再慢慢感受双手。','感受胸腔随呼吸起伏，吸入柔软，呼出紧绷。','允许念头来来去去，不用抓住，也不用驱赶。','让身体一点点沉向支撑，安稳地停留在这里。'],
 '思绪杂乱':['让每一个念头像水面上的叶子，不必追赶，慢慢经过。','如果注意力又跑远了，也没有关系。轻轻留意身边的一点声音。','把注意力放回身体接触床面或椅子的地方，念头可以暂时留在那里。','允许自己暂时没有答案，在这里安静待一会儿。'],
 '疲惫':['找到舒服的姿势。无需用力，让身体被安稳地承托。','留意双手放在哪里，肩膀靠在哪里，给身体一点不必忙碌的时间。','如果愿意，可以轻轻闭眼，也可以保持睁眼，按舒服的方式休息。','不必再完成什么，给自己一点不被催促的时间。']
}
const guidance=computed(()=>steps[state.value][step.value])
function chooseState(value){state.value=value;step.value=0;if(remaining.value){startedAt=Date.now();stepDuration=Math.max(1,deadline-startedAt)/4}}
let startedAt=0,stepDuration=0
const time=computed(()=>Math.floor(remaining.value/60)+":"+String(remaining.value%60).padStart(2,"0"))
function stop(){clearInterval(timer);remaining.value=0;step.value=0;message.value="练习已停下，按自己的节奏就好。"}
function start(){clearInterval(timer);minutes.value=Math.max(1,Math.min(30,Math.round(Number(minutes.value)||3)));remaining.value=minutes.value*60;startedAt=Date.now();step.value=0;stepDuration=remaining.value*1000/4;deadline=startedAt+remaining.value*1000;message.value="";timer=setInterval(()=>{step.value=Math.min(3,Math.floor((Date.now()-startedAt)/stepDuration));remaining.value=Math.max(0,Math.ceil((deadline-Date.now())/1000));if(!remaining.value){clearInterval(timer);message.value="这段放松已结束，可以继续休息，也可以给今夜留一颗种子。"}},250)}
function finish(){stop();router.push("/dream/cues")}
onBeforeUnmount(()=>clearInterval(timer))
</script>
<template>
 <section v-if="compact" class="j-panel compact-relax" aria-labelledby="compact-relax-heading">
  <header><h2 id="compact-relax-heading">睡前放松</h2><div class="compact-states" role="group" aria-label="此刻的状态"><button v-for="s in ['紧绷','思绪杂乱','疲惫']" :key="s" :aria-pressed="state===s" @click="chooseState(s)">{{s}}</button></div><label class="compact-duration"><span class="j-sr">留给自己几分钟</span><select v-model.number="minutes" :disabled="remaining>0" aria-label="留给自己几分钟"><option v-for="n in [1,3,5,10,15,20,30]" :key="n" :value="n">留给自己 {{n}} 分钟</option></select></label></header>
  <div class="compact-practice"><div class="compact-start"><p>{{steps[state][0]}}</p><div class="j-row"><button v-if="!remaining" @click="start">开始放松</button><button v-else @click="stop">随时停下</button></div></div><div class="relax-orb" :class="{running:remaining>0}"><span>慢慢安顿<small v-if="remaining">{{time}}</small></span></div><div class="compact-guidance"><p aria-live="polite">{{guidance}} 自然呼吸就好，不必刻意跟随光圈。</p><button class="j-primary" @click="finish">结束，种下今夜种子</button></div></div>
  <p v-if="message" role="status">{{message}}</p><p class="compact-footer">练习没有对错，觉得不适随时都可以停下。仅用于个人感受观察，不具备医疗、心理诊疗、解梦占卜功能。</p>
 </section>
 <section v-else class="j-panel bedtime-relaxation" aria-labelledby="relax-heading">
  <h2 id="relax-heading">睡前放松</h2><p>把白天的疲惫慢慢放下。选择此刻当下的状态，留几分钟温柔地陪着自己。练习没有对错，觉得不适随时都可以停下。</p>
  <div class="j-row" role="group" aria-label="此刻的状态"><button v-for="s in ['紧绷','思绪杂乱','疲惫']" :key="s" :aria-pressed="state===s" :class="{'j-selected':state===s}" @click="chooseState(s)">{{s}}</button></div>
  <label class="relax-duration">留给自己几分钟<input v-model.number="minutes" type="number" aria-label="练习时长（分钟）" min="1" max="30" step="1"></label>
  <div class="relax-practice">
   <div class="breath-heading"><h3>跟着呼吸慢慢安顿</h3><p>◌ 吸气 <b>4</b> 秒</p><p>◌ 呼气 <b>6</b> 秒</p></div>
   <div class="relax-orbit"><div class="relax-orb" :class="{running:remaining>0}"><span>慢慢安顿<small v-if="remaining">{{time}}</small></span></div></div>
   <ol class="relax-steps"><li v-for="(line,i) in steps[state]" :key="state+i" :class="{current:remaining>0&&step===i}" :aria-current="remaining>0&&step===i?'step':undefined"><span aria-hidden="true">✓</span><div>第{{i+1}}步：{{line}}</div></li></ol>
   <p class="relax-guidance" aria-live="polite" aria-atomic="true">{{remaining?guidance:''}}</p>
   <div class="body-scan"><h3>身体扫描</h3><p>从头顶到脚尖，依次感受每一处。不需要改变什么，只是看见它。</p></div>
  </div>
  <aside class="relax-tip" aria-label="小提示"><h3>小提示</h3><p>不用强迫自己放空大脑，也不用逼自己睡着。</p><p>如果思绪跑远了，轻轻回到呼吸就好。</p><small>自然呼吸就好，不必刻意跟随光圈。</small></aside>
  <div class="relax-actions"><p>白天已经结束，现在只属于你和夜晚。</p><div class="j-row"><button class="j-primary" @click="start">{{remaining?'重新开始':'开始放松'}}</button><button v-if="remaining" @click="stop">随时停下</button><button @click="finish">结束，种下今夜种子</button></div></div>
  <p v-if="message" role="status">{{message}}</p>
  <p class="relax-footer">本工具仅用于个人感受观察，不具备医疗、心理诊疗、解梦占卜功能。</p>
 </section>
</template>
